-- Write your PostgreSQL query statement below
SELECT s.student_id,s.student_name,su.subject_name,count(e.student_id) attended_exams FROM Subjects su CROSS JOIN Students s LEFT JOIN Examinations e ON s.student_id = e.student_id AND e.subject_name = su.subject_name GROUP BY s.student_id,s.student_name,su.subject_name 